window.CARD_CODE="import React from 'react';\r\n\r\nimport type {\r\n  Control,\r\n  FieldValues,\r\n  FormProviderProps,\r\n  UseFormReturn,\r\n} from './types';\r\nimport { HookFormControlContext } from './useFormControlContext';\r\n\r\nconst HookFormContext = React.createContext<UseFormReturn | null>(null);\r\nHookFormContext.displayName = 'HookFormContext';\r\n\r\n/**\r\n * Retrieves all `useForm` methods from the nearest `FormProvider`.\r\n * Use in deeply nested components to avoid prop-drilling.\r\n *\r\n * @see [API](https://react-hook-form.com/docs/useformcontext)\r\n *\r\n * @example\r\n * ```tsx\r\n * const { register } = useFormContext<FormValues>();\r\n * ```\r\n */\r\nexport const useFormContext = <\r\n  TFieldValues extends FieldValues,\r\n  TContext = any,\r\n  TTransformedValues = TFieldValues,\r\n>(): UseFormReturn<TFieldValues, TContext, TTransformedValues> =>\r\n  React.useContext(HookFormContext) as UseFormReturn<\r\n    TFieldValues,\r\n    TContext,\r\n    TTransformedValues\r\n  >;\r\n\r\n/**\r\n * Provides all `useForm` methods to the component tree via React Context.\r\n * Pair with `useFormContext` to consume them in any descendant.\r\n *\r\n * @see [API](https://react-hook-form.com/docs/useformcontext)\r\n *\r\n * @example\r\n * ```tsx\r\n * <FormProvider {...methods}>\r\n *   <form onSubmit={methods.handleSubmit(onSubmit)}>{children}</form>\r\n * </FormProvider>\r\n * ```\r\n */\r\nexport const FormProvider = <\r\n  TFieldValues extends FieldValues,\r\n  TContext = any,\r\n  TTransformedValues = TFieldValues,\r\n>({\r\n  children,\r\n  watch,\r\n  getValues,\r\n  getErrors,\r\n  getFieldState,\r\n  setError,\r\n  clearErrors,\r\n  setValue,\r\n  setValues,\r\n  trigger,\r\n  formState,\r\n  resetField,\r\n  reset,\r\n  resetDefaultValues,\r\n  handleSubmit,\r\n  unregister,\r\n  control,\r\n  register,\r\n  setFocus,\r\n  subscribe,\r\n}: FormProviderProps<TFieldValues, TContext, TTransformedValues>) => {\r\n  const memoizedValue = React.useMemo<\r\n    UseFormReturn<TFieldValues, TContext, TTransformedValues>\r\n  >(\r\n    () => ({\r\n      watch,\r\n      getValues,\r\n      getErrors,\r\n      getFieldState,\r\n      setError,\r\n      clearErrors,\r\n      setValue,\r\n      setValues,\r\n      trigger,\r\n      formState,\r\n      resetField,\r\n      reset,\r\n      resetDefaultValues,\r\n      handleSubmit,\r\n      unregister,\r\n      control,\r\n      register,\r\n      setFocus,\r\n      subscribe,\r\n    }),\r\n    [\r\n      clearErrors,\r\n      control,\r\n      formState,\r\n      getErrors,\r\n      getFieldState,\r\n      getValues,\r\n      handleSubmit,\r\n      register,\r\n      reset,\r\n      resetDefaultValues,\r\n      resetField,\r\n      setError,\r\n      setFocus,\r\n      setValue,\r\n      setValues,\r\n      subscribe,\r\n      trigger,\r\n      unregister,\r\n      watch,\r\n    ],\r\n  );\r\n\r\n  return (\r\n    <HookFormContext.Provider value={memoizedValue as unknown as UseFormReturn}>\r\n      <HookFormControlContext.Provider value={memoizedValue.control as Control}>\r\n        {children}\r\n      </HookFormControlContext.Provider>\r\n    </HookFormContext.Provider>\r\n  );\r\n};\r\n";
